code.body:
domains:
  customer_refunds:
    autonomy: act                      # earned: 99% success over 500 runs
    bounds: { max_amount_usd: 200, reversible_only: true }
    gates: [ { trigger: "amount > 200", action: require_approval },
             { trigger: "recipient_count > 10", action: require_approval } ]
    escalation: { on: [failures>=3, confidence<0.6], package: full }

  infrastructure_changes:
    autonomy: recommend                # not yet earned
    gates: [ { trigger: "always", action: require_approval } ]

global:
  kill_switch: { scope: [per_agent, all], drill: quarterly }
  rollback: { backups: automatic, runbook: v3, signoff: oncall_lead }
  audit: { append_only: true, includes: [gates, levels, escalations, actions] }
